    std::array<float, kOut> z{};
    float mx = -1e30f;
    for (int k = 0; k < kOut; ++k) {
        z[k] = kB2[k];
        for (int j = 0; j < kHidden; ++j) z[k] += (h[j] > 0 ? h[j] : 0.0f) * kW2[j * kOut + k];
        mx = z[k] > mx ? z[k] : mx;
    }
    float s = 0;
    for (auto& v : z) { v = std::exp(v - mx); s += v; }
    for (auto& v : z) v /= s;
    return z;
